<template>
 <div v-if="modelValue" class="helper-overlay"><section role="dialog" aria-modal="true" aria-label="帮砍详情" class="helper-dialog"><header><div><h3>帮砍详情</h3><p>参与记录 #{{ recordId }} · 活动 #{{ activityLabel }}</p></div><button v-for="control in controls" :key="control.key" type="button" aria-label="关闭帮砍详情" @click="control.close">关闭</button></header>
 <div class="helper-body"><p v-if="!session.allowed.value" role="alert">当前账号没有此详情查看权限</p><p v-if="error" role="alert" class="bad">{{ error }}</p><button v-for="control in controls" :key="control.key" type="button" :disabled="loading || !session.allowed.value" @click="control.retry">重新读取详情</button><p v-if="loading" role="status">正在读取帮砍记录…</p><div class="table-scroll"><table aria-label="帮砍记录"><thead><tr><th>用户</th><th>帮砍金额（元）</th><th>来源</th><th>时间</th></tr></thead><tbody><tr v-for="row in helpers" :key="row.id"><td><img v-if="image(row.avatar_preview)" :src="image(row.avatar_preview)" alt="帮砍用户头像" />{{ row.nickname || '历史用户' }} / {{ row.uid }}<small v-if="row.deleted_user">已注销</small><small v-if="row.missing_user">用户资料缺失</small><small v-if="row.issues.length" class="bad">{{ row.issues.join('；') }}</small></td><td>{{ row.price }}</td><td>{{ row.type===0?'好友帮砍':row.type===1?'发起者自砍':'历史类型 #'+row.type }}</td><td>{{ time(row.add_time) }}</td></tr></tbody></table></div><p v-if="!loading && !error && !helpers.length">暂无帮砍记录</p></div>
 <footer><span>第 {{ page }} 页 · 共 {{ count }} 条（每页15条）</span><template v-for="control in controls" :key="control.key"><button type="button" :disabled="loading || page<=1" @click="control.previous">上一页</button><button type="button" :disabled="loading || page*15>=count || page>=667" @click="control.next">下一页</button><button type="button" @click="control.close">关闭详情</button></template></footer></section></div>
</template>
<script setup lang="ts">
import {computed,ref} from 'vue';
import {useRoute} from 'vue-router';
import {apiBargainHelpers,apiBargainStatisticsHelpers,bargainPreview as image,bargainReadError,type BargainHelper} from '@/api/bargainRecords';
import {useBargainReadSession,bargainReadTime as time} from './bargainReadSession';
const props=defineProps<{modelValue:boolean;recordId:number;activityId?:number;sourceCurrent?:()=>boolean}>(),emit=defineEmits<{ 'update:modelValue':[value:boolean] }>();
const route=useRoute(),helpers=ref<BargainHelper[]>([]),page=ref(1),count=ref(0),loading=ref(false),error=ref(''),activityLabel=ref<number|string>('—'),intent=ref(0);
function discard(){helpers.value=[];page.value=1;count.value=0;loading.value=false;error.value='';activityLabel.value='—';intent.value++;}
const session=useBargainReadSession(()=>props.activityId===undefined?'bargain_record.view':'bargain_statistics.view',()=>JSON.stringify([route.fullPath,props.modelValue,props.recordId,props.activityId,props.sourceCurrent?.()??true]),discard,()=>{if(props.modelValue&&(props.sourceCurrent?.()??true))void load(1);});
async function load(target=page.value){if(!props.modelValue || !(props.sourceCurrent?.()??true) || !Number.isSafeInteger(target)||target<1||target>667)return;const job=session.begin('helpers');if(!job)return;const record=props.recordId,activity=props.activityId;intent.value++;helpers.value=[];count.value=0;page.value=target;loading.value=true;error.value='';try{const q={page:target,limit:15};const data=activity===undefined?await apiBargainHelpers(record,q,job.signal):await apiBargainStatisticsHelpers(activity,record,q,job.signal);if(job.current()){helpers.value=data.list;count.value=data.count;activityLabel.value=data.bargain_id;}}catch(reason){if(job.current())error.value=bargainReadError(reason,'帮砍详情读取失败');}finally{if(job.current())loading.value=false;job.finish();}}
const controls=computed(()=>{const view=session.lease(),version=intent.value,current=()=>view.current()&&version===intent.value&&props.modelValue&&(props.sourceCurrent?.()??true);return [{key:view.key+':'+props.recordId,close:()=>{if(current()){session.invalidate();emit('update:modelValue',false);}},retry:()=>{if(current())void load(page.value);},previous:()=>{if(current()&&!loading.value&&page.value>1)void load(page.value-1);},next:()=>{if(current()&&!loading.value&&page.value*15<count.value)void load(page.value+1);}}];});
</script>
<style scoped>
.helper-overlay{position:fixed;inset:0;z-index:2100;display:grid;place-items:center;padding:16px;background:#0006}.helper-dialog{display:flex;flex-direction:column;width:min(850px,100%);max-height:calc(100dvh - 32px);background:#fff;border-radius:8px;min-width:0;overflow:hidden}header,footer{display:flex;gap:10px;align-items:center;justify-content:space-between;padding:16px;border-bottom:1px solid #e5e7eb;flex-wrap:wrap}header h3{margin:0;font-size:18px}header p{margin:5px 0 0;color:#747b87;font-size:13px}.helper-body{padding:16px;overflow:auto;min-height:0}footer{border:0;border-top:1px solid #e5e7eb;flex-shrink:0;font-size:13px}.table-scroll{overflow:auto;max-width:100%}table{border-collapse:collapse;width:100%;min-width:580px;font-size:13px}th,td{text-align:left;border:1px solid #e5e7eb;padding:10px;vertical-align:top}td img{width:32px;height:32px;object-fit:cover;float:left;margin-right:8px}small{display:block}button{font:inherit;background:#fff;border:1px solid #dcdfe6;border-radius:4px;padding:6px 10px;color:#356ac3;cursor:pointer}button:disabled{opacity:.5;cursor:default}.bad{color:#c45656}@media(max-width:500px){.helper-overlay{padding:12px}.helper-dialog{max-height:calc(100dvh - 24px)}header,.helper-body,footer{padding:12px}footer span{flex-basis:100%}}
</style>
